import { combineReducers, configureStore } from "@reduxjs/toolkit";
import { setupListeners } from "@reduxjs/toolkit/query";
import authReducer from "./reducers/auth";
import appConfigReducer from "./slices/appConfigSlice";
import { useDispatch, useSelector } from "react-redux";
import i18nReducer from "./reducers/i18n";
import navigationReducer from "./slices/navigationSlice";
import { pendingTabNavigationIntentMiddleware } from "./middleware/pendingTabNavigationIntentMiddleware";
const rootReducer = combineReducers({
  auth: authReducer,
  info: appConfigReducer,
  i18n: i18nReducer,
  navigation: navigationReducer
});
const store = configureStore({
  reducer: rootReducer,
  middleware: (getDefaultMiddleware) => getDefaultMiddleware({
    serializableCheck: {
      ignoredActions: ["auth/loadSecurityInfo/fulfilled"],
      ignoredActionPaths: ["meta.arg", "payload.config", "payload.request"],
      ignoredPaths: ["auth.securityConfig"]
    }
  }).concat(pendingTabNavigationIntentMiddleware)
});
if (typeof window !== "undefined") {
  setupListeners(store.dispatch);
}
const useAppDispatch = useDispatch;
const useAppSelector = useSelector;
export {
  store,
  useAppDispatch,
  useAppSelector
};
