import { createSlice } from "@reduxjs/toolkit";
const initialState = {
  pendingAccordionExpansion: null,
  pendingTabSelection: null
};
const navigationSlice = createSlice({
  name: "navigation",
  initialState,
  reducers: {
    setPendingAccordionExpansion: (state, action) => {
      state.pendingAccordionExpansion = action.payload;
    },
    clearPendingAccordionExpansion: (state) => {
      state.pendingAccordionExpansion = null;
    },
    setPendingTabSelection: (state, action) => {
      state.pendingTabSelection = action.payload;
    },
    clearPendingTabSelection: (state) => {
      state.pendingTabSelection = null;
    }
  }
});
const {
  setPendingAccordionExpansion,
  clearPendingAccordionExpansion,
  setPendingTabSelection,
  clearPendingTabSelection
} = navigationSlice.actions;
var navigationSlice_default = navigationSlice.reducer;
export {
  clearPendingAccordionExpansion,
  clearPendingTabSelection,
  navigationSlice_default as default,
  setPendingAccordionExpansion,
  setPendingTabSelection
};
